  ctx.fillStyle = cssVar("--paper"); ctx.fillRect(sx(0), sy(H), W * view.k, H * view.k);
  ctx.restore();

  const bases = P?.baselines?.map((b) => b - S.typography.baseline_shift) || [];
  if (S.preview.show_ruling) {
    ctx.save();
