  const g = glyphAt(x, y);
  if (!g) { $("picked").textContent = ""; return; }
  $("picked").innerHTML = `<b>word ${g.w}, letter ${g.l}</b> «${esc(g.c)}» → resume from it`;
  S.text_options.resume_word = g.w;
  S.text_options.resume_letter = g.l;
