const zoneOf = () => S.drawing.a3.enabled ? S.drawing.a3 : S.drawing.marked;
const runTurn = (q) => S.drawing.a3.enabled ? A3_TURN[A3_RUNS.indexOf(q.rotation)] : q.rotation === 180 ? "лист повёрнут на 180°" : "лист по меткам";
const markedText = (q) => S.drawing.a3.enabled ? `Перед заходом: <b>${runTurn(q)}</b>; рисуется то, что в зоне` : q.rotation === 180 ? "Лист <b>повёрнут на 180°</b>, на тех же метках; рисуется то, что в зоне"
  : "Лист <b>на метках</b>; рисуется то, что в зоне";
const aff = (m, p) => [m[0] * p[0] + m[1] * p[1] + m[4], m[2] * p[0] + m[3] * p[1] + m[5]];
function markedCorners(part) {
  const [W, H] = sheetWH();
  return [[0, 0], [W, 0], [W, H], [0, H]].map((p) => aff(part.m, p));
}
function markedSvg(part) {
  const cs = markedCorners(part), xs = cs.map((p) => p[0]).concat(0), ys = cs.map((p) => p[1]).concat(0);
  const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys);
  const k = Math.min(110 / (x1 - x0), 88 / (y1 - y0)), px = (x) => 9 + (x - x0) * k, py = (y) => 96 - (y - y0) * k;
  let s = `<polygon points="${cs.map((p) => `${px(p[0])},${py(p[1])}`).join(" ")}" style="fill:var(--paper)" stroke="#888"/>`;
  const reg = part.region, rc = [[reg[0], reg[1]], [reg[2], reg[1]], [reg[2], reg[3]], [reg[0], reg[3]]].map((p) => aff(part.m, p));
  s += `<polygon points="${rc.map((p) => `${px(p[0])},${py(p[1])}`).join(" ")}" fill="${rgba(part.rotation, .35)}"/>`;
  s += `<line x1="${px(x0)}" y1="${py(0)}" x2="${px(x1)}" y2="${py(0)}" stroke="#c0392b" stroke-dasharray="3 2"/>`;
  s += `<circle cx="${px(0)}" cy="${py(0)}" r="3" fill="#2f5fb3"/>`;
  return `<svg viewBox="0 0 128 104">${s}</svg>`;
}
function cardSvg(part) {
  if (part.m) return markedSvg(part);

  const [W, H] = sheetWH(), r = part.rotation, [Wp, Hp] = part.pass_size;
  const k = Math.min(110 / Wp, 80 / Hp), px = (x) => 12 + x * k, py = (y) => 92 - y * k;
  const a = toPass([part.region[0], part.region[1]], r, W, H), b = toPass([part.region[2], part.region[3]], r, W, H);
  const cx0 = Math.max(0, Math.min(a[0], b[0])), cx1 = Math.min(Wp, Math.max(a[0], b[0]));
  const cy0 = Math.max(0, Math.min(a[1], b[1])), cy1 = Math.min(Hp, Math.max(a[1], b[1]));
  let s = `<rect x="${px(0)}" y="${py(Hp)}" width="${Wp * k}" height="${Hp * k}" style="fill:var(--paper)" stroke="#888"/>`;
  s += `<rect x="${px(cx0)}" y="${py(cy1)}" width="${(cx1 - cx0) * k}" height="${(cy1 - cy0) * k}" fill="${rgba(r, .35)}"/>`;
  const win = P.passes.windows[r].safe;
  s += `<rect x="${px(Math.max(win[0], 0))}" y="${py(Math.min(win[3], Hp))}" width="${(Math.min(win[2], Wp) - Math.max(win[0], 0)) * k}" height="${(Math.min(win[3], Hp) - Math.max(win[1], 0)) * k}" fill="none" stroke="#c0392b" stroke-dasharray="3 2"/>`;
  s += `<path d="M${px(0) - 3} ${py(Hp * 0.4)} V${py(0) + 3} H${px(Wp * 0.4)}" fill="none" stroke="#333" stroke-width="3"/>`;
  s += `<circle cx="${px(0)}" cy="${py(0)}" r="3" fill="#2f5fb3"/>`;
  for (const [name, c] of Object.entries(P.passes.corners)) {
    const [x, y] = toPass(c, r, W, H);
    s += `<text x="${px(x) + (x > 0 ? 2 : -9)}" y="${py(y) + (y > 0 ? -2 : 10)}" font-size="9" font-weight="bold" fill="${name === part.corner ? rgba(r, 1) : "#666"}">${name}</text>`;
