}
function esc(s) { return String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }

function bindFields() {
  document.querySelectorAll("[data-path]").forEach((el) => {
    if (el === document.activeElement && el.type === "number") return;
