  });
  const t = S.printer.travel;
  $("travelMeasured").checked = !!t;
  const reach = (a, b, flip) => Math.max(0, ...(flip ? [-a, -b] : [a, b]));
  [["work_w", t && reach(t.x_min, t.x_max, S.printer.flip_x)], ["work_h", t && reach(t.y_min, t.y_max, S.printer.flip_y)]].forEach(([k, v]) => {
