  $("workHint").textContent = t ? "The reach window is measured — the work area is taken from it (the fields above only show the size)."
    : "How far the pencil travels from zero (the sheet corner at the stops) along X and Y. If the window below is measured, it is used instead.";
  if (t) lastTravel = { ...t };
  document.querySelectorAll("[data-travel]").forEach((el) => { el.value = lastTravel[el.dataset.travel]; el.disabled = !t; });
  document.querySelectorAll("[data-table]").forEach((el) => {
