const PASS_COLORS = { 0: [47, 95, 179], 90: [39, 150, 90], 180: [214, 120, 20], 270: [140, 70, 180] };
const rgba = (r, a) => `rgba(${PASS_COLORS[r].join(",")},${a})`;
