function renderPassInfo() {
  const ps = P.passes;
  if (!ps) { $("passInfo").innerHTML = ""; return; }
  $("a3Box").style.display = S.drawing.a3.enabled ? "" : "none";
  $("a4Box").style.display = S.drawing.a3.enabled ? "none" : "";
  if (P.marked && S.drawing.a3.enabled) {
