}
function wizardProblems(w) {
  const e = [];
  if (!w) return ["Enter all four readings at the limits"];
  if (!(w.x_min <= 0 && 0 <= w.x_max)) e.push("Zero (the sheet corner) is outside the window in X: check the corner and ±X readings");
  if (!(w.y_min <= 0 && 0 <= w.y_max)) e.push("Zero (the sheet corner) is outside the window in Y: check the corner and ±Y readings");
  const m = S.printer.safety_margin;
  if (w.x_max - w.x_min <= 2 * m || w.y_max - w.y_min <= 2 * m) e.push("The window is smaller than two margins along one of the axes");
