}
function wizardUpdate() {
  const r = readings();
  const w = wizardWindow(r);
  const probs = wizardProblems(w);
  const m = S.printer.safety_margin;
  $("wzResult").innerHTML = w
    ? `Window relative to zero: X ${w.x_min}…${w.x_max}, Y ${w.y_min}…${w.y_max} mm; ` +
      `with margin ${m} mm: X ${(w.x_min + m).toFixed(1)}…${(w.x_max - m).toFixed(1)}, Y ${(w.y_min + m).toFixed(1)}…${(w.y_max - m).toFixed(1)}.`
    : "";
