  const f = Math.exp(-e.deltaY * 0.0015);
  const k = Math.min(200, Math.max(0.2, view.k * f));
  const wx = (mx - view.ox) / view.k, wy = (view.oy - my) / view.k;
  view.k = k; view.ox = mx - wx * k; view.oy = my + wy * k; view.auto = false;
