  else if (el.type === "number") {
    if (el.value === "" || isNaN(Number(el.value))) return;
    v = Number(el.value);
    if (/pdf_page|passes|threshold$/.test(path)) v = Math.round(v);
  } else v = el.value;
  setPath(S, path, v);
  bindFields();
  changed(path === "drawing.show_travel" ? "redraw" : "full");
}
