    if (sc.paper_size) h += `, on paper ${sc.paper_size[0]}×${sc.paper_size[1]} mm`;
    if (P.sheet) h += `<br><span class="kv">Sheet ${P.sheet.width}×${P.sheet.height} mm, ${P.sheet.orientation === "portrait" ? "portrait" : "landscape"}.`;
