const PASS_COLORS = { 0: [47, 95, 179], 90: [39, 150, 90], 180: [214, 120, 20], 270: [140, 70, 180] };
const rgba = (r, a) => `rgba(${PASS_COLORS[r].join(",")},${a})`;
const CORNER_NAME = { A: "bottom left", B: "bottom right", C: "top right", D: "top left" };

function renderPassInfo() {
  const ps = P.passes;
  if (!ps) { $("passInfo").innerHTML = ""; return; }
  $("a3Box").style.display = S.drawing.a3.enabled ? "" : "none";
  $("a4Box").style.display = S.drawing.a3.enabled ? "none" : "";
  if (P.marked && S.drawing.a3.enabled) {
    $("passInfo").innerHTML = `<div class="turn">A3 sheet, runs: ${P.parts.length}: between runs rotate the sheet by 180°, then by 90° clockwise, then by 180°. The pencil starts at 0, 0 and returns there.</div>`;
    return;
  }
  if (P.marked) {
    $("passInfo").innerHTML = `<div class="turn">${P.parts.length === 1 ? "One run is enough" : `Runs: ${P.parts.length}: before run 2, rotate the sheet by 180° and put it on the same marks`}. The pencil starts at 0, 0 and returns there.</div>`;
    return;
  }
  const sw = (r) => `<span class="sw" style="background:${rgba(r, .55)}"></span>`;
  const desc = (r) => `${sw(r)}${r}°, corner at the stops ${ps.corner_of[r]} (${CORNER_NAME[ps.corner_of[r]]})`;
  let h = "";
  if (ps.rotation != null && ps.rotation !== 0)
    h += `<div class="turn">The drawing is made in one pass with the sheet rotated ${esc(ps.rotation_text)}. Put this corner against the stops; the zero is there.</div>`;
  const sp = ps.sheet_plan;
  if (sp.rotations) {
    h += `<div><b>Working area of the sheet:</b> passes ${sp.rotations.length} — ${sp.rotations.map(desc).join("; ")}.</div>`;
  } else {
    h += `<div class="msg warn">⚠ ${esc(sp.message)}</div>`;
  }
  if (ps.drawing) {
    h += `<div><b>Drawing:</b> ${ps.drawing.length === 1 ? "one pass" : "passes " + ps.drawing.length} — ${ps.drawing.map(desc).join("; ")}.</div>`;
  }
  if (ps.notes.length) h += `<div class="kv">Rotations not allowed: ${ps.notes.map(esc).join("; ")}.</div>`;
  $("passInfo").innerHTML = h;
}

function renderFileInfo() {
  const im = P.import;
