  ctx.beginPath(); cs.forEach((p, i) => (i ? ctx.lineTo : ctx.moveTo).call(ctx, sx(p[0]), sy(p[1]))); ctx.closePath(); ctx.fill(); ctx.restore();
  const reg = part.region, rc = [[reg[0], reg[1]], [reg[2], reg[1]], [reg[2], reg[3]], [reg[0], reg[3]]].map(T);
  ctx.save(); ctx.fillStyle = rgba(part.rotation, .08); ctx.beginPath();
  rc.forEach((p, i) => (i ? ctx.lineTo : ctx.moveTo).call(ctx, sx(p[0]), sy(p[1]))); ctx.closePath(); ctx.fill(); ctx.restore();
  const mk = zoneOf(part);
  ctx.save(); ctx.setLineDash([7, 4]); ctx.strokeStyle = "#c0392b"; ctx.lineWidth = 1.3;
  ctx.strokeRect(sx(mk.x_min), sy(mk.y_max), (mk.x_max - mk.x_min) * view.k, (mk.y_max - mk.y_min) * view.k); ctx.restore();
  label(`work area X ${mk.x_min}–${mk.x_max}, Y ${mk.y_min}–${mk.y_max}`, sx(mk.x_max) - 4, sy(mk.y_min) + 14, "#c0392b", "right");
  drawSeams(T);
  if (S.drawing.show_travel) {
    ctx.save(); ctx.setLineDash([4, 4]); ctx.lineWidth = 0.8; ctx.strokeStyle = "rgba(226,120,30,.7)"; ctx.beginPath();
    for (const [a, b, k] of P.travel) if (k === part.index) { const p = T(a), q = T(b); ctx.moveTo(sx(p[0]), sy(p[1])); ctx.lineTo(sx(q[0]), sy(q[1])); }
    ctx.stroke(); ctx.restore();
  }
  drawStrokes(T, part.index);
  ctx.save(); ctx.fillStyle = "#2f5fb3"; ctx.beginPath(); ctx.arc(sx(0), sy(0), 5, 0, Math.PI * 2); ctx.fill(); ctx.restore();
  label("0, 0 — pencil start", sx(0) + 8, sy(0) - 8, "#2f5fb3");
  ctx.save(); ctx.font = "bold 13px system-ui"; ctx.fillStyle = cssVar("--muted");
  for (const [name, c] of Object.entries(P.passes.corners)) { const [x, y] = T(c); ctx.fillText(name, sx(x) + (x > 0 ? 4 : -14), sy(y) + (y > 0 ? -4 : 16)); }
  ctx.fillStyle = rgba(part.rotation, 1);
  const w = (areaPanels.at(-1)?.cw || cv.getBoundingClientRect().width) - 20;
  ctx.fillText(fitText(`Run ${part.index} of ${P.parts.length} · ${runTurn(part)}`, w), ox + 10, oy + 18);
  ctx.font = "12px system-ui"; ctx.fillStyle = cssVar("--muted");
  ctx.fillText(fitText("how the sheet lies on the printer; what is inside the work area is drawn", w), ox + 10, oy + 36);
  ctx.restore();
}
function drawTable(part, ox = 0, oy = 0, brief = false) {
  if (part.m) return drawMarked(part, ox, oy, brief);

  const [W, H] = sheetWH(), r = part.rotation, [Wp, Hp] = part.pass_size;
  const T = (p) => { const q = toPass(p, r, W, H); return [q[0] + part.dx, q[1] + part.dy]; };
  const win = P.passes.windows[r], tb = P.passes.table;
  const rect = ([x0, y0, x1, y1], fill, stroke, dash) => {
    ctx.save(); if (dash) ctx.setLineDash(dash);
    if (fill) { ctx.fillStyle = fill; ctx.fillRect(sx(x0), sy(y1), (x1 - x0) * view.k, (y1 - y0) * view.k); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = 1.2; ctx.strokeRect(sx(x0), sy(y1), (x1 - x0) * view.k, (y1 - y0) * view.k); }
    ctx.restore();
  };
  rect([0, 0, tb.table_x, tb.table_y], cssVar("--chip"), tb.given ? "#9aa3ad" : null, null);
  ctx.save(); ctx.shadowColor = "rgba(0,0,0,.18)"; ctx.shadowBlur = 10;
  ctx.fillStyle = cssVar("--paper"); ctx.fillRect(sx(0), sy(Hp), Wp * view.k, Hp * view.k); ctx.restore();

  const [c0, c1] = [T([part.region[0], part.region[1]]), T([part.region[2], part.region[3]])];
  rect([Math.min(c0[0], c1[0]), Math.min(c0[1], c1[1]), Math.max(c0[0], c1[0]), Math.max(c0[1], c1[1])], rgba(r, .08), null, null);
  rect(win.raw, null, "#c0392b", [7, 4]);
  label(`work area ${Math.round(win.raw[2] - win.raw[0])}×${Math.round(win.raw[3] - win.raw[1])} mm`, sx(win.raw[2]) + 6, sy(win.raw[3]) + 4, "#c0392b");
  rect(win.safe, null, "rgba(192,57,43,.6)", null);
  drawSeams(T);
  if (S.drawing.show_travel) {
    ctx.save(); ctx.setLineDash([4, 4]); ctx.lineWidth = 0.8; ctx.strokeStyle = "rgba(226,120,30,.7)"; ctx.beginPath();
    for (const [a, b, k] of P.travel) if (k === part.index) { const p = T(a), q = T(b); ctx.moveTo(sx(p[0]), sy(p[1])); ctx.lineTo(sx(q[0]), sy(q[1])); }
    ctx.stroke(); ctx.restore();
  }
  drawStrokes(T, part.index);

  ctx.save(); ctx.strokeStyle = cssVar("--text"); ctx.lineWidth = 5;
  ctx.beginPath(); ctx.moveTo(sx(0) - 4, sy(Math.min(60, Hp))); ctx.lineTo(sx(0) - 4, sy(0) + 4); ctx.lineTo(sx(Math.min(60, Wp)), sy(0) + 4); ctx.stroke();
  ctx.fillStyle = "#2f5fb3"; ctx.beginPath(); ctx.arc(sx(0), sy(0), 5, 0, Math.PI * 2); ctx.fill();
  ctx.font = "bold 13px system-ui"; ctx.fillStyle = cssVar("--muted");
  for (const [name, c] of Object.entries(P.passes.corners)) {
    const [x, y] = toPass(c, r, W, H);
    ctx.fillText(name, sx(x) + (x > 0 ? 4 : -14), sy(y) + (y > 0 ? -4 : 16));
  }
  ctx.fillStyle = rgba(r, 1); ctx.font = "bold 13px system-ui";
  if (brief) {
    const w = (areaPanels.at(-1)?.cw || cv.getBoundingClientRect().width) - 20;
    ctx.fillText(fitText(`Area ${part.index} of ${P.parts.length} · rotation ${r}°`, w), ox + 10, oy + 18);
    ctx.font = "12px system-ui"; ctx.fillStyle = cssVar("--muted");
    ctx.fillText(fitText(`corner at the stops ${part.corner} (${part.corner_name}), the zero is there`, w), ox + 10, oy + 36);
  } else {
    ctx.fillText(`Area ${part.index}: the sheet as it lies on the table — rotation ${r}°, corner at the stops ${part.corner} (${part.corner_name}), the zero is there`, ox + 10, oy + 20);
  }
